struct Source {StableId kind,command,policy;const VisitMessageContact* contact=nullptr;};
std::optional<Integer> serial(const StableId& id,const StableId& prefix,Integer next=INT64_MAX){const auto start=prefix+":";if(id.rfind(start,0)!=0)return {};const auto text=id.substr(start.size());Integer n=0;auto p=std::from_chars(text.data(),text.data()+text.size(),n);if(text.empty()||p.ec!=std::errc{}||p.ptr!=text.data()+text.size()||n<1||n>=next||std::to_string(n)!=text)return {};return n;}
Source source(const VisitMessageState& s,const StableId& id){if(const auto* p=s.posted.find(id))return {visit_message_posted_kind,"leave_visit_message",p->policy_id,&p->contact};for(const auto* table:{&s.received,&s.withdrawn})if(const auto* t=table->find(id)){const auto* p=s.posted.find(t->message_fact_id);if(!p)return {};const bool received=table==&s.received;return {received?visit_message_received_kind:visit_message_withdrawn_kind,received?"receive_visit_message":"withdraw_visit_message",p->policy_id,&t->contact};}return {};}
bool command(const StableId& kind){return kind=="leave_visit_message"||kind=="receive_visit_message"||kind=="withdraw_visit_message";}
bool tagged(const StableId& id){return id.rfind(StableId{visit_message_posted_kind}+":",0)==0||id.rfind(StableId{visit_message_received_kind}+":",0)==0||id.rfind(StableId{visit_message_withdrawn_kind}+":",0)==0;}
bool advance_kind(const StableId& kind){return kind=="advance"||kind=="wait"||kind=="travel_wait"||kind=="duel_start"||kind=="encounter_fight"||kind=="dialogue_confirm";}
bool advance_shape(const StableId& kind,const ReceiptDetails& details){if(kind=="advance"||kind=="wait"||kind=="travel_wait")return std::holds_alternative<AdvanceDetails>(details.data);if(kind=="duel_start"||kind=="encounter_fight"){const auto* personal=std::get_if<PersonalReceipt>(&details.data);return personal&&!personal->battle_id.empty();}if(kind=="dialogue_confirm")return std::holds_alternative<Done>(details.data)||std::holds_alternative<AdvanceDetails>(details.data)||(std::holds_alternative<PersonalReceipt>(details.data)&&!std::get<PersonalReceipt>(details.data).battle_id.empty());return false;}
Status actual(const Source& s,const StableId& id,const StableId& producer,const StableId& request_actor,const StableId& kind,Integer tick,const ReceiptDetails& details){if(!s.contact||s.contact->tick!=tick)return common_failure("VisitMessageActualSourceRequired",id);if(producer=="director")return advance_shape(kind,details)?common_success():common_failure("VisitMessageActualAdvanceRequired",id);const auto* effect=std::get_if<InteractionEffect>(&details.data);if((producer!="player"&&producer!="director_actor")||s.command!=kind||s.contact->actor_id!=request_actor||!effect||effect->settlement_result!=id||!effect->encounter_id.empty()||effect->party_id||effect->person_id||effect->news_ids)return common_failure("VisitMessageActualSourceRequired",id);return common_success();}
// NPC来源必须原本人显式routine、原Talk认领以及同场原接待人；不读今日Director计划倒造旧办理。
Outcome<const VisitReceptionClaim*> npc_claim(const CommonStore& c,const VisitMessageReceiptRead& r,const Source& s,const StableId& id){auto fail=[&]()->Outcome<const VisitReceptionClaim*>{return {false,nullptr,common_failure("VisitMessageOriginalNpcClaimRequired",id).error};};if(!r.reception||!r.claims||!s.contact||s.kind==visit_message_withdrawn_kind)return fail();const auto* intent=visit_reception_actor_intent(*r.reception,s.contact->actor_id);if(!intent||intent->message_policy_id!=s.policy||intent->purpose!=(s.kind==visit_message_posted_kind?"deposit":"receive"))return fail();const auto* claim=read_visit_reception_claim(*r.claims,s.contact->session_id,s.contact->actor_id,intent->id);const auto* head=claim?c.state().facts.find(claim->fact_id):nullptr;const auto n=claim?serial(claim->fact_id,"visit_reception_claim",c.state().next_instance_id):std::optional<Integer>{};const auto origin=serial(id,s.kind,c.state().next_instance_id);const auto& order=c.state().facts.order();const auto ci=claim?std::find(order.begin(),order.end(),claim->fact_id):order.end(),fi=std::find(order.begin(),order.end(),id);if(!claim||!head||head->id!=claim->fact_id||head->kind!=visit_reception_claim_kind||head->domain!=visit_reception_claim_module||!n||!origin||*n>=*origin||ci==order.end()||fi==order.end()||ci>=fi||claim->tick>s.contact->tick||claim->policy_id!=s.policy||claim->provider_actor_id!=s.contact->custodian_actor_id||claim->role_id!=s.contact->role_id||claim->dialogue_id!=s.contact->dialogue_id||claim->place_id!=s.contact->place_id)return fail();return {true,claim,{}};}
bool same(const SourceRef&a,const SourceRef&b){return a.domain==b.domain&&a.kind==b.kind&&a.id==b.id;}
bool same(const VisitMessageResultBinding&a,const VisitMessageResultBinding&b){return a.fact_id==b.fact_id&&a.producer==b.producer&&a.request_actor_id==b.request_actor_id&&a.result_id==b.result_id&&a.claim_fact_id==b.claim_fact_id&&a.intent_id==b.intent_id&&a.result_kind==b.result_kind&&a.request_sequence==b.request_sequence&&a.result_revision==b.result_revision&&a.from_tick==b.from_tick;}
Outcome<DirectorAcceptedCommandView> director_command(const CommonStore&common,const VisitMessageReceiptRead&read,const StableId&actor,Integer request,const StableId&result){
 if(!read.director_commands||!read.actual_clock)return {false,{},common_failure("VisitMessageDirectorActorSourcesRequired",{},ErrorKind::unsupported_capability).error};const auto&x=*read.director_commands;
 if(!x.state.subject2)return {false,{},common_failure("VisitMessageDirectorPhysical6Required",{},ErrorKind::unsupported_capability).error};
 const DirectorAdoptionResult2*found=nullptr;for(const auto&row:x.state.subject2->adoption_results.rows())if(row.second.accepted_command&&row.second.accepted_command->result_id==result){if(found)return {false,{},common_failure("VisitMessageDirectorResultAliased",result).error};found=&row.second;}
 if(!found||!found->accepted_command)return {false,{},common_failure("VisitMessageActualActorAdoptionRequired",result).error};const auto&c=*found->accepted_command;
 auto value=read_director_accepted_command(common,x.state,x.catalog,x.identity,{actor,found->registration_epoch,found->decision_seq,c.command_kind,request,result});if(!value.ok)return value;
 auto now=read.actual_clock->read_current_moment();if(!now.ok)return {false,{},now.error};auto time=compare_world_moments(c.accepted_at,now.value);if(!time.ok)return {false,{},time.error};if(time.value>0)return {false,{},common_failure("VisitMessageActorCommandFromFuture",result).error};return value;
}
Status actor_claim_sources(const CommonStore&common,const VisitMessageReceiptRead&read){if(!read.reception||!read.claims||!read.interactions||!read.interaction_state||!read.actual_clock)return common_failure("VisitMessageDirectorOriginalClaimSourcesRequired",{},ErrorKind::unsupported_capability);return validate_visit_reception_claims(common,*read.claims,*read.reception,read.catalog,*read.interactions,*read.interaction_state,read.actual_clock,read.actual_occupancy);}
Status actor_origin(const CommonStore&common,const VisitMessageReceiptRead&read,const Source&s,const StableId&id,const VisitMessageResultBinding&row){
 auto claims=actor_claim_sources(common,read);if(!claims.ok)return claims;auto original=director_command(common,read,row.request_actor_id,row.request_sequence,row.result_id);if(!original.ok)return {false,{},original.error};const auto&c=*original.value.command;const auto&result=*original.value.actual_result;
 if(!s.contact||c.actor_id!=s.contact->actor_id||c.command_kind!=s.command||c.command_kind!=row.result_kind||c.accepted_at.half_day_tick!=s.contact->tick||row.from_tick!=c.accepted_at.half_day_tick||result.revision!=row.result_revision||c.actual_effect.source_schema!=1||!same(c.actual_effect.source_ref,{"visit_messages",s.kind,id})||!result.details)return common_failure("VisitMessageDirectorActorIdentityMismatch",id);
 auto valid=actual(s,id,"director_actor",row.request_actor_id,result.kind,result.tick,*result.details);if(!valid.ok)return valid;auto claim=npc_claim(common,read,s,id);if(!claim.ok)return {false,{},claim.error};if(row.claim_fact_id!=claim.value->fact_id||row.intent_id!=claim.value->intent_id)return common_failure("VisitMessageNpcOriginMismatch",id);return common_success();
}
std::size_t count(const VisitMessageState& s){return s.posted.size()+s.received.size()+s.withdrawn.size();}
